import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.Bx7X8BVG.js";const k=JSON.parse('{"title":"Docker 版：Linux 服务器与 NAS","description":"","frontmatter":{},"headers":[],"relativePath":"guide/docker.md","filePath":"guide/docker.md","lastUpdated":null}'),t={name:"guide/docker.md"};function l(p,s,d,r,h,o){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="docker-版-linux-服务器与-nas" tabindex="-1">Docker 版：Linux 服务器与 NAS <a class="header-anchor" href="#docker-版-linux-服务器与-nas" aria-label="Permalink to &quot;Docker 版：Linux 服务器与 NAS&quot;">​</a></h1><p>适合希望隧道持续运行的服务器和 NAS。安装前需要 Docker Engine、Docker Compose 和 Git，并确认可以访问 Cloudflare 网络。</p><h2 id="架构与支持范围" tabindex="-1">架构与支持范围 <a class="header-anchor" href="#架构与支持范围" aria-label="Permalink to &quot;架构与支持范围&quot;">​</a></h2><p>仓库使用 Node Alpine 和 cloudflared 基础镜像构建。amd64/arm64 能否安装，取决于<strong>所选基础镜像及加速站是否提供对应架构</strong>。已有 ARM fnOS 用户运行反馈，但 v1.8.1 桌面 CI <strong>不等于 ARM Docker 完整验收</strong>。32 位 ARM 未验证。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/lieren2012/cloudflare-tunnel-manager.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudflare-tunnel-manager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>也可在预定安装父目录执行脚本：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/lieren2012/cloudflare-tunnel-manager/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>脚本会测速选择<strong>代码拉取源</strong>；不自动安装 Docker/Git，也不对 Docker 镜像下载速度进行完整测速。基础镜像仍按 Compose 的配置拉取。第三方加速站可能失效，<a href="/cloudflare-tunnel-manager/guide/update#不同下载源不要混用">切换镜像源</a>。</p><div class="tip custom-block"><p class="custom-block-title">安装目录</p><p>记录最终项目目录，后续始终在同一个目录升级。不要在旧项目里再克隆出一个同名子目录，否则新容器可能挂载新的空 data。</p></div><h2 id="访问与验收" tabindex="-1">访问与验收 <a class="header-anchor" href="#访问与验收" aria-label="Permalink to &quot;访问与验收&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:19090/api/auth/state</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>容器应运行，接口应返回 <code>success: true</code>。新数据目录返回 <code>needsSetup: true</code>；已有账号则为 false。浏览器打开 <code>http://服务器局域网IP:19090</code>。</p><table tabindex="0"><thead><tr><th>默认端口</th><th>用途</th></tr></thead><tbody><tr><td>19090</td><td>Web 面板</td></tr><tr><td>19092</td><td>外部 API，需 API Key</td></tr><tr><td>19093</td><td>MCP，需 API Key</td></tr></tbody></table><p>默认 host 网络主要面向 Linux；Docker Desktop 的网络行为不同，不建议直接照搬到 Windows/macOS，优先使用桌面版。端口冲突需要在 Compose 的 <code>environment</code> 中显式设置 WEB_PORT/API_PORT/MCP_PORT；仅在 <code>.env</code> 写入未被 Compose 引用的变量不会生效。</p><h2 id="数据与备份" tabindex="-1">数据与备份 <a class="header-anchor" href="#数据与备份" aria-label="Permalink to &quot;数据与备份&quot;">​</a></h2><p>默认 <code>./data:/data</code> 保存账号、配置、会话和隧道。升级前备份整个目录，同时保存 <code>.env</code> 和 <code>docker-compose.override.yml</code>。备份含敏感凭据，不要公开上传。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在实际项目目录执行；停服务使备份一致</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data.backup.$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y%m%d-%H%M%S)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>如果忘记目录：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf-tunnel-manager</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{{range .Mounts}}{{println .Source &quot;-&gt;&quot; .Destination}}{{end}}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>以 <code>/app</code> 和 <code>/data</code> 的宿主机挂载源为准。更新不会主动删除 data，但错误挂载、手动删除或磁盘问题仍可能造成数据不可用。</p><h2 id="升级与卸载" tabindex="-1">升级与卸载 <a class="header-anchor" href="#升级与卸载" aria-label="Permalink to &quot;升级与卸载&quot;">​</a></h2><p>升级见 <a href="/cloudflare-tunnel-manager/guide/update">更新教程</a>。在实际项目目录执行 <code>bash uninstall.sh</code>，确认后删除容器，默认保留 data。它不是卸载 Docker，不会删除 Cloudflare 云端隧道和 DNS。若要停用云端隧道，另在面板/Cloudflare 后台处理。</p>`,23)])])}const u=a(t,[["render",l]]);export{k as __pageData,u as default};
